import{_ as e,o as n,c as s,ag as i}from"./chunks/framework.PVHj0As1.js";const t="/pub-blog/assets/image-20241124191241104.IQAUpNV6.png",o="/pub-blog/assets/image-20241124191300505.CSyse3xt.png",r="/pub-blog/assets/image-20241124191643071.Ci7LEgrm.png",p="/pub-blog/assets/image-20241124191744693.BBoTzSSW.png",g="/pub-blog/assets/image-20241124191327227.BWJ6xVnJ.png",l="/pub-blog/assets/image-20241124191343134.BGNv5Uz3.png",m="/pub-blog/assets/PixPin_2024-11-24_19-15-16.CyY0klIC.gif",c="/pub-blog/assets/image-20241124191814129.DNBl_n2X.png",h="/pub-blog/assets/image-20241124192132959.D-zWMOTI.png",b="/pub-blog/assets/image-20241127095335272.BfNnDY52.png",_="/pub-blog/assets/image-20241127102037596.h6WJnT9C.png",u="/pub-blog/assets/image-20241127102233557.xE0kjQfQ.png",d="/pub-blog/assets/image-20241127103001436.DxWcjtHF.png",P="/pub-blog/assets/image-20241127111351966.CW_De0IJ.png",f="/pub-blog/assets/0000000000011111111.20241108162413.21428389402407934282631586754603.j1rv_0RU.png",x="/pub-blog/assets/image-20241127103329588.BHDdSnTp.png",q="/pub-blog/assets/image-20241127103441091.D3pje6a0.png",A="/pub-blog/assets/image-20241127103512816.DOraYl3g.png",k="/pub-blog/assets/0000000000011111111.20241108162413.94137298091598438736514604862804.CWFDEGh3.png",C="/pub-blog/assets/0000000000011111111.20241108162413.37859214279609577220399148607883.DVQAmSbt.png",S="/pub-blog/assets/image-20241127103940121.DgwmzSpH.png",y="/pub-blog/assets/image-20241127104028586.BQrskgEz.png",D="/pub-blog/assets/image-20241127104100616.BlxT98of.png",G="/pub-blog/assets/image-20241127104421049.Cf2C-dPI.png",O="/pub-blog/assets/image-20241127104501011.D9SrchIu.png",H="/pub-blog/assets/image-20241127104552646.B00YOXp4.png",I="/pub-blog/assets/image-20241127104809629.CEnaXKAY.png",B="/pub-blog/assets/image-20241127104905347.BxMu0tQw.png",N="/pub-blog/assets/image-20241127105255233.CcG1RqhI.png",v="/pub-blog/assets/image-20241127105420075.FHq05XE3.png",j="/pub-blog/assets/image-20241127105504102.MiCaAARK.png",T="/pub-blog/assets/image-20241127105615225.Bfk2qs4t.png",R="/pub-blog/assets/image-20241127105819036.D3kgfTLx.png",E="/pub-blog/assets/image-20241127110100621.fQ0ibPkM.png",w="/pub-blog/assets/image-20241127110412484.Dq5jJDQU.png",Q="/pub-blog/assets/image-20241127110440114.B5dMAIXx.png",J="/pub-blog/assets/image-20241127110908371.BEH6chpg.png",M="/pub-blog/assets/image-20241127110949471.kiF1M_63.png",W="/pub-blog/assets/image-20241127111044105.BsCixUJn.png",L=JSON.parse('{"title":"HarmonyOS Next 元服务新建到上架全流程","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS Next 元服务新建到上架全流程/HarmonyOS Next 元服务新建到上架全流程.md","filePath":"鸿蒙开发技巧/HarmonyOS Next 元服务新建到上架全流程/HarmonyOS Next 元服务新建到上架全流程.md","lastUpdated":1751381397000,"__rawMarkdown":"# HarmonyOS Next 元服务新建到上架全流程\\n\\n接上篇\\n\\n这篇文章的主要目的是介绍元服务从新建到上家的完整流程\\n\\n# 在AGC平台上新建一个项目\\n\\n[链接](https://developer.huawei.com/consumer/cn/service/josp/agc/index.html#/harmonyOSDevPlatform/172249065903274453)\\n\\n一个项目可以多个应用\\n\\n![image-20241124191241104](assets/image-20241124191241104.png)\\n\\n# AGC新建一个元服务应用\\n\\n![image-20241124191300505](assets/image-20241124191300505.png)\\n\\n# 新建一个本地元服务项目\\n\\n![image-20241124191643071](assets/image-20241124191643071.png)\\n\\n---\\n\\n如果成功在AGC平台上新建过元服务，那么这里会自动显示\\n\\n![image-20241124191744693](assets/image-20241124191744693.png)\\n\\n# 修改元服务名称\\n\\n![image-20241124191327227](assets/image-20241124191327227.png)\\n\\n# 修改元服务图标\\n\\n重要，上架审核很严谨\\n\\n![image-20241124191343134](assets/image-20241124191343134.png)\\n\\n1. 先自己下载随意一张图片\\n\\n2. 使用画图工具  图像属性 修改 1024px\\n\\n   ![PixPin_2024-11-24_19-15-16](assets/PixPin_2024-11-24_19-15-16.gif)\\n\\n3. 使用开发工具中 Image Asset  来制作图片\\n\\n![image-20241124191814129](assets/image-20241124191814129.png)\\n\\n![image-20241124192132959](assets/image-20241124192132959.png)\\n\\n\\n\\n# 发布流程\\n\\n![image-20241127095335272](assets/image-20241127095335272.png)\\n\\n# 介绍签名文件\\n\\n- **密钥**：包含非对称加密中使用的公钥和私钥，存储在密钥库文件中，格式为**.p12**，公钥和私钥对用于数字签名和验证。\\n- **证书请求文件**：格式为**.csr**，全称为Certificate Signing Request，包含密钥对中的公钥和公共名称、组织名称、组织单位等信息，用于向AppGallery Connect申请数字证书。\\n- **数字证书**：格式为**.cer**，由华为AppGallery Connect颁发。\\n- **Profile文件**：格式为**.p7b**，包含HarmonyOS应用/元服务的包名、数字证书信息、描述应用/元服务允许申请的证书权限列表，以及允许应用/元服务调试的设备列表（如果应用/元服务类型为Release类型，则设备列表为空）等内容，每个应用/元服务包中均必须包含一个Profile文件。\\n\\n其中，多个元服务可以共用、**.p12**、**.csr**、**.cer**。也就是说**.p7b** 需要每一个项目单独生成一次\\n\\n\\n\\n# 生成密钥和证书请求文件\\n\\n> 此操作会得到两个文件\\n\\n![image-20241127102037596](assets/image-20241127102037596.png)\\n\\n---\\n\\n![image-20241127102233557](assets/image-20241127102233557.png)\\n\\n---\\n\\n![image-20241127103001436](assets/image-20241127103001436.png)\\n\\n# 申请发布证书和Profile文件\\n\\n> 此操作也会得到两个文件\\n\\n## 申请发布证书步骤如下：\\n\\n1. 登录[AppGallery Connect](https://developer.huawei.com/consumer/cn/service/josp/agc/index.html#/)，选择**“证书、APP ID和Profile”**。\\n\\n   ![image-20241127111351966](assets/image-20241127111351966.png)\\n\\n2. 在左侧导航栏选择“**证书、APP ID和Profile > 证书**”，进入“证书”页面，点击“**新增证书**”。\\n\\n   ![img](assets/0000000000011111111.20241108162413.21428389402407934282631586754603.png)\\n\\n3. 在弹出的“新增证书”窗口填写要申请的证书信息，点击“提交”。\\n\\n   ![image-20241127103329588](assets/image-20241127103329588.png)\\n\\n4. 下载 cer\\n\\n   ![image-20241127103441091](assets/image-20241127103441091.png)\\n\\n5. **得到发布证书**\\n\\n![image-20241127103512816](assets/image-20241127103512816.png)\\n\\n## 申请发布Profile\\n\\nProfile格式为.p7b，包含HarmonyOS应用/元服务的包名、数字证书信息、HarmonyOS应用/元服务允许申请的证书权限列表，以及允许应用/元服务调试的设备列表（如果应用/元服务类型为Release类型，则设备列表为空）等内容。每个HarmonyOS应用/元服务包中均必须包含一个Profile文件\\n\\n申请发布Profile步骤如下：\\n\\n1. 登录 AppGallery Connect，选择**证书、APP ID和Profile**\\n\\n   ![img](assets/0000000000011111111.20241108162413.94137298091598438736514604862804.png)\\n\\n2. 在左侧导航栏选择**“证书、APP ID和Profile \\\\> Profile”**，进入“**Profile**”页面，点击右上角**“添加”**。\\n\\n   ![img](assets/0000000000011111111.20241108162413.37859214279609577220399148607883.png)\\n\\n   \\n\\n3. 在“**添加Profile**”页面，填写**Profile**信息，完成后点击“添加”。\\n\\n   ![image-20241127103940121](assets/image-20241127103940121.png)\\n\\n4. 下载 Profile\\n\\n   ![image-20241127104028586](assets/image-20241127104028586.png)\\n\\n5. 得到ProFile文件\\n\\n   ![image-20241127104100616](assets/image-20241127104100616.png)\\n\\n\\n\\n# 手动签名\\n\\n让你的元服务使用刚才的证书进行手动签名\\n\\n![image-20241127104421049](assets/image-20241127104421049.png)\\n\\n# 打包构建\\n\\n![image-20241127104501011](assets/image-20241127104501011.png)\\n\\n得到APP文件\\n\\n![image-20241127104552646](assets/image-20241127104552646.png)\\n\\n# 新建发布\\n\\n回到AGC平台，新建发布\\n\\n![image-20241127104809629](assets/image-20241127104809629.png)\\n\\n# 编辑发布资料\\n\\n![image-20241127104905347](assets/image-20241127104905347.png)\\n\\n---\\n\\n![image-20241127105255233](assets/image-20241127105255233.png)\\n\\n---\\n\\n![image-20241127105420075](assets/image-20241127105420075.png)\\n\\n# 备案域名\\n\\n\\n\\n此时，如果你的应用没有备案，是会被拒绝的。这里的备案是说，你既要有一个备案过的域名+备案的元服务\\n\\n一个根域名可以对应多个元服务。如\\n\\na.baidu.com  元服务A\\n\\nb.baidu.com  元服务B\\n\\n![image-20241127105504102](assets/image-20241127105504102.png)\\n\\n\\n\\n备案对于新手来说也是一个大的步骤，所以真想要发布一个应用的话，尽量先备案\\n\\n[腾讯云参考链接：](https://juejin.cn/post/6844903840165134344#heading-5)\\n\\n![image-20241127105615225](assets/image-20241127105615225.png)\\n\\n---\\n\\n这一步执行完毕，你会得到一个自己的[备案过的域名](https://console.cloud.tencent.com/domain/all-domain/all)\\n\\n![image-20241127105819036](assets/image-20241127105819036.png)\\n\\n# 备案元服务\\n\\n备案网站、应用、元服务都是一样的流程\\n\\n[备案元服务](https://console.cloud.tencent.com/beian/manage)\\n\\n![image-20241127110100621](assets/image-20241127110100621.png)\\n\\n---\\n\\n填写备案信息\\n\\n![image-20241127110412484](assets/image-20241127110412484.png)\\n\\n# 审核备案\\n\\n![image-20241127110440114](assets/image-20241127110440114.png)\\n\\n1. 当你填写完毕后，腾讯云会给你电话，如果你信息填写不对，他们会协助你修改的。一般当天会来电话。\\n\\n2. 腾讯云审核通过了，会进入到**管局审核阶段**，可能会来电话，也可能不来。都是通过了的话，你手机会受到一条短信。必须当天把短信中的验证码填写的[管局备案系统](https://beian.miit.gov.cn/#/Integrated/index)上。此时，备案流程结束\\n\\n   ![image-20241127110908371](assets/image-20241127110908371.png)\\n\\n![image-20241127110949471](assets/image-20241127110949471.png)\\n\\n# AGC重新提交审核\\n\\n![image-20241127111044105](assets/image-20241127111044105.png)\\n\\n# 后续\\n\\n后续继续关注AGC平台信息即可\\n\\n"}'),F={name:"鸿蒙开发技巧/HarmonyOS Next 元服务新建到上架全流程/HarmonyOS Next 元服务新建到上架全流程.md"};function U(V,a,z,X,Y,$){return n(),s("div",null,[...a[0]||(a[0]=[i("",86)])])}const Z=e(F,[["render",U]]);export{L as __pageData,Z as default};
